#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long a;
    char op;
    long long b;
    cin >> a >> op >> b;

    if (op == '+') {
        cout << a + b << endl;
    } else if (op == '-') {
        cout << a - b << endl;
    } else if (op == '*') {
        cout << a * b << endl;
    } else {
        cout << a / b << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        char op = sc.next().charAt(0);
        long b = sc.nextLong();

        if (op == '+') {
            System.out.println(a + b);
        } else if (op == '-') {
            System.out.println(a - b);
        } else if (op == '*') {
            System.out.println(a * b);
        } else {
            System.out.println(a / b);
        }
    }
}
